import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api'; // Assuming you have `updateExamData` and `deleteExamData` functions

const ExamData = () => {
  const [franchiseId, setFranchiseId] = useState('');
  const [filterFranchiseId, setFilterFranchiseId] = useState(''); // State to store filter
  const [franchises, setFranchises] = useState([]); // Store the list of franchises
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [examDataList, setExamDataList] = useState([]); // Store the list of exam data
  const [editIndex, setEditIndex] = useState(null); // Track the index being edited

  // Fetch franchises on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises(); // Fetch list of franchises
        setFranchises(response.data); // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []); // Run once when the component mounts

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFranchiseChange = (e) => {
    setFranchiseId(e.target.value);
  };

  const handleFilterChange = (e) => {
    setFilterFranchiseId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editIndex !== null) {
        // Update existing exam data
        const updatedExam = { ...formData, franchiseId };
        setExamDataList((prev) => {
          const updatedList = [...prev];
          updatedList[editIndex] = updatedExam;
          return updatedList;
        });
        setEditIndex(null);
        alert('Exam data updated successfully!');
      } else {
        // Add new exam data
        const newExam = { ...formData, franchiseId };
        setExamDataList((prev) => [...prev, newExam]);
        alert('Exam data created successfully!');
      }

      // Reset the form
      setFormData({
        examName: '',
        date: '',
        studentsAttended: '',
      });
      setFranchiseId('');
    } catch (error) {
      alert('Error updating/creating exam data: ' + (error.response?.data?.message || error.message));
      console.error('Error:', error);
    }
  };

  const handleEdit = (index) => {
    const examToEdit = examDataList[index];
    setFormData({
      examName: examToEdit.examName,
      date: examToEdit.date,
      studentsAttended: examToEdit.studentsAttended,
    });
    setFranchiseId(examToEdit.franchiseId);
    setEditIndex(index);
  };

  const handleDelete = (index) => {
    if (window.confirm('Are you sure you want to delete this exam data?')) {
      setExamDataList((prev) => prev.filter((_, i) => i !== index));
      alert('Exam data deleted successfully!');
    }
  };

  const getFranchiseName = (id) => {
    const franchise = franchises.find((f) => f._id === id);
    return franchise ? franchise.name : 'Unknown Franchise';
  };

  // Filter exam data based on selected franchise
  const filteredExamData = examDataList.filter(
    (exam) => !filterFranchiseId || exam.franchiseId === filterFranchiseId
  );

  return (
    <div>
      <h1>Manage Exam Data</h1>
      <div>
        <div>
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={franchiseId}
            onChange={handleFranchiseChange}
            required
          >
            <option value="">Select Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
          <select
            id="filterFranchiseId"
            name="filterFranchiseId"
            value={filterFranchiseId}
            onChange={handleFilterChange}
          >
            <option value="">All</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="examName">Exam Name:</label>
          <input
            id="examName"
            name="examName"
            placeholder="Enter Exam Name"
            value={formData.examName}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="studentsAttended">Students Attended:</label>
          <input
            id="studentsAttended"
            name="studentsAttended"
            type="number"
            placeholder="Number of Students"
            value={formData.studentsAttended}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit">{editIndex !== null ? 'Update' : 'Create'} Exam Data</button>
      </form>

      <h2>Exam Data</h2>
      {filteredExamData.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Franchise Name</th>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredExamData.map((exam, index) => (
              <tr key={index}>
                <td>{getFranchiseName(exam.franchiseId)}</td>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
                <td>
                  <button onClick={() => handleEdit(index)}>Edit</button>
                  <button onClick={() => handleDelete(index)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default ExamData;
